window.PORTFOLIO_PROJECTS = {"version":6,"order":["print-orchestrator","pfc-supervisor","hermes","ai-server","e3ng","voron-systems","metuned","motorsports","espresso-machine","uei-lab","abb-rexroth","makerspace-manufacturing"],"projects":{"print-orchestrator":{"id":"print-orchestrator","tone":"blue","eyebrow":"AI automation frontend","title":"Print Orchestrator","lede":"A mixed-fleet control layer that gives Hermes a safe, inspectable way to create, prepare, dispatch, monitor, and power printer jobs.","status":["Active","Private project","PrusaLink + Moonraker/Klipper"],"image":"assets/screenshots/print-orchestrator-dashboard-v6.png","imageAlt":"Print Orchestrator fleet dashboard","imageCaption":"Live mixed-fleet control panel.","imageFit":"contain","gallery":[{"src":"assets/screenshots/print-orchestrator-dashboard-v6.png","alt":"Print Orchestrator fleet dashboard","title":"Fleet control","copy":"PrusaLink and Moonraker/Klipper machines share one operator view without losing machine-specific controls.","kind":"screenshot","orientation":"portrait"},{"src":"assets/screenshots/print-orchestrator-power.png","alt":"Print Orchestrator power observation page","title":"Power observation","copy":"Kasa smart-plug telemetry tracks printers and the B70 server while also enabling remote power control.","kind":"screenshot","orientation":"portrait"},{"src":"assets/images/pi-case-render.png","alt":"Parametric Raspberry Pi enclosure prepared for printing","title":"AI-assisted CAD output","copy":"This enclosure is an output artifact from the prototype OpenSCAD and slicing workflow; full unattended operation is still being validated.","orientation":"landscape"},{"src":"assets/images/pfp-server-pi-case.jpg","alt":"Raspberry Pi enclosure installed on the PFP server","title":"Installed enclosure","copy":"The printed enclosure is mounted on the server and supports the low-power control node used by the wider automation stack.","orientation":"portrait"}],"metrics":[{"value":"3 printers","label":"mixed fleet in the current dashboard"},{"value":"AI vision","label":"failure warnings through Discord"},{"value":"Bed check","label":"part-detection start interlock"},{"value":"Kasa","label":"power telemetry and control"}],"tabs":[{"id":"overview","label":"Overview","html":"<div class=\"project-section-heading compact\"><div><p class=\"project-eyebrow\">Overview</p><h2>A printer dashboard that also acts as an automation API.</h2></div></div><div class=\"project-overview-grid\"><article><p class=\"project-eyebrow\">Operator view</p><h3>One place for the fleet</h3><p>Jobs, cameras, temperatures, power, part detection, files, and recovery states are kept together.</p></article><article><p class=\"project-eyebrow\">Automation role</p><h3>Hermes controls physical work through it</h3><p>Print Orchestrator exposes the machine state and actions needed for AI-assisted CAD, slicing, dispatch, and monitoring.</p></article></div>"},{"id":"engineering","label":"Engineering","html":"<div class=\"project-section-heading compact\"><div><p class=\"project-eyebrow\">Engineering</p><h2>The API keeps automation tied to real machine state.</h2></div></div><div class=\"project-decision-grid compact-decisions\"><article class=\"project-decision\"><span>01</span><div><h3>Preserve machine differences</h3><p>PrusaLink and Moonraker/Klipper devices keep their actual capabilities and limits.</p></div></article><article class=\"project-decision\"><span>02</span><div><h3>Block unsafe starts</h3><p>Part detection can prevent a job from starting while an object remains on the bed.</p></div></article><article class=\"project-decision\"><span>03</span><div><h3>Separate detection from action</h3><p>Vision warnings, operator review, and control actions remain distinct so a model result does not silently become a machine command.</p></div></article></div>"},{"id":"pipeline","label":"Automation","html":"<div class=\"project-section-heading compact\"><div><p class=\"project-eyebrow\">Automation pipeline</p><h2>Hermes can turn a request into a controlled printer workflow</h2></div></div><div class=\"automation-pipeline\"><article><span>01</span><h3>Prompt / job request</h3><p>Hermes receives a part request or a prepared model.</p></article><article><span>02</span><h3>Parametric CAD</h3><p>OpenSCAD scripts can be generated or modified from a prompt.</p></article><article><span>03</span><h3>CLI slicing</h3><p>A modified OrcaSlicer command-line path prepares G-code.</p></article><article><span>04</span><h3>Preflight checks</h3><p>Printer state, power, connectivity, and bed occupancy are checked.</p></article><article><span>05</span><h3>API dispatch</h3><p>Print Orchestrator selects and controls the appropriate machine.</p></article><article><span>06</span><h3>Vision monitoring</h3><p>A modified Obico container evaluates camera frames and can warn through Discord.</p></article></div><p class=\"project-caveat\"><strong>Status:</strong> the backend pipeline is implemented in parts and remains under end-to-end validation. The Pi enclosure is an output artifact from the prototype workflow; fully unattended production is still being validated.</p>"},{"id":"power","label":"Power","html":"<div class=\"project-section-heading compact\"><div><p class=\"project-eyebrow\">Power</p><h2>Kasa smart plugs connect energy telemetry to printer automation</h2></div></div><div class=\"savings-kpi-grid blue-kpis\"><article><strong>Fleet + server</strong><span>printer and B70 power telemetry</span></article><article><strong>Remote control</strong><span>safe power-on and power-off actions</span></article><article><strong>Hermes-ready</strong><span>actions exposed to scripts and automations</span></article></div><figure class=\"single-documentation\"><button type=\"button\" data-lightbox data-caption=\"Print Orchestrator power observation page\"><img src=\"assets/screenshots/print-orchestrator-power.png\" alt=\"Print Orchestrator power observation page\"></button><figcaption>Power history, device averages, state, and availability are reported per Kasa outlet.</figcaption></figure>"},{"id":"documentation","label":"Documentation","html":"<div class=\"project-section-heading compact\"><div><p class=\"project-eyebrow\">Documentation</p><h2>Control panels and a prototype workflow output.</h2></div></div><div class=\"project-gallery documentation-carousel gallery-count-4\"><figure class=\"screenshot portrait\"><button type=\"button\" data-lightbox data-caption=\"Fleet control — PrusaLink and Moonraker/Klipper machines share one operator view without losing machine-specific controls.\"><img loading=\"lazy\" src=\"assets/screenshots/print-orchestrator-dashboard-v6.png\" alt=\"Print Orchestrator fleet dashboard\"></button><figcaption><strong>Fleet control</strong>PrusaLink and Moonraker/Klipper machines share one operator view without losing machine-specific controls.</figcaption></figure><figure class=\"screenshot portrait\"><button type=\"button\" data-lightbox data-caption=\"Power observation — Kasa smart-plug telemetry tracks printers and the B70 server while also enabling remote power control.\"><img loading=\"lazy\" src=\"assets/screenshots/print-orchestrator-power.png\" alt=\"Print Orchestrator power observation page\"></button><figcaption><strong>Power observation</strong>Kasa smart-plug telemetry tracks printers and the B70 server while also enabling remote power control.</figcaption></figure><figure class=\"landscape\"><button type=\"button\" data-lightbox data-caption=\"AI-assisted CAD output — This enclosure is an output artifact from the prototype OpenSCAD and slicing workflow; full unattended operation is still being validated.\"><img loading=\"lazy\" src=\"assets/images/pi-case-render.png\" alt=\"Parametric Raspberry Pi enclosure prepared for printing\"></button><figcaption><strong>AI-assisted CAD output</strong>This enclosure is an output artifact from the prototype OpenSCAD and slicing workflow; full unattended operation is still being validated.</figcaption></figure><figure class=\"portrait\"><button type=\"button\" data-lightbox data-caption=\"Installed enclosure — The printed enclosure is mounted on the server and supports the low-power control node used by the wider automation stack.\"><img loading=\"lazy\" src=\"assets/images/pfp-server-pi-case.jpg\" alt=\"Raspberry Pi enclosure installed on the PFP server\"></button><figcaption><strong>Installed enclosure</strong>The printed enclosure is mounted on the server and supports the low-power control node used by the wider automation stack.</figcaption></figure></div>"},{"id":"results","label":"Results","html":"<div class=\"project-section-heading compact\"><div><p class=\"project-eyebrow\">Results</p><h2>The printer fleet now has one automation-ready control surface.</h2></div></div><div class=\"project-outcome-grid compact-outcomes\"><article><span>01</span><h3>Shared fleet state</h3><p>Mixed printer protocols are translated into a consistent operator and API model.</p></article><article><span>02</span><h3>Safer automation</h3><p>Power, bed occupancy, connectivity, and failure warnings are visible before actions are taken.</p></article><article><span>03</span><h3>Foundation for autonomy</h3><p>The current system can grow toward automatic resetting and part removal without redesigning the software boundary.</p></article></div>"},{"id":"future","label":"Future Work","html":"<div class=\"project-section-heading compact\"><div><p class=\"project-eyebrow\">Current R&amp;D</p><h2>Move from assisted orchestration toward a repeatable print cell.</h2></div></div><div class=\"project-flow compact-flow\"><article><span>01</span><h3>End-to-end validation</h3><p>Test prompt-to-CAD, slicing, preflight, dispatch, and monitoring as one measured workflow.</p></article><article><span>02</span><h3>Robotic reset</h3><p>Add a mechanism that can remove finished parts and prepare the bed for the next job.</p></article><article><span>03</span><h3>Production reporting</h3><p>Track job yield, failure causes, intervention time, and energy per completed part.</p></article></div>"},{"id":"references","label":"References","html":"<div class=\"project-section-heading compact\"><div><p class=\"project-eyebrow\">References</p><h2>Upstream projects and technical references</h2></div></div><div class=\"reference-callout\"><p>Print Orchestrator is Joseph&#x27;s private control and automation project. It integrates established open-source tools rather than claiming their upstream work.</p><p><strong>My work:</strong> API design, mixed-fleet normalization, power integration, part-detection interlocks, Hermes workflows, modified CLI slicing, modified Obico deployment, and the control interface.</p><div class=\"project-reference-list\"><a class=\"project-reference-chip\" href=\"https://openscad.org/documentation\" rel=\"noreferrer\" target=\"_blank\">OpenSCAD docs <span>↗</span></a><a class=\"project-reference-chip\" href=\"https://github.com/OrcaSlicer/OrcaSlicer\" rel=\"noreferrer\" target=\"_blank\">OrcaSlicer <span>↗</span></a><a class=\"project-reference-chip\" href=\"https://www.obico.io/blog/how-obico-ai-failure-detection-works/\" rel=\"noreferrer\" target=\"_blank\">Obico failure detection <span>↗</span></a><a class=\"project-reference-chip\" href=\"https://www.klipper3d.org/\" rel=\"noreferrer\" target=\"_blank\">Klipper docs <span>↗</span></a></div></div>"}],"next":"Validate the full automated workflow and add physical part removal only after the safety and recovery paths are measured.","fallbackPage":"projects/print-orchestrator/"},"pfc-supervisor":{"id":"pfc-supervisor","tone":"green","eyebrow":"Power and runtime control plane","title":"PFC Supervisor","lede":"A supervisory layer that coordinates local AI runtimes, server sleep, protected schedules, recovery, and energy reporting across the PFP/B70 infrastructure.","status":["Active","Private project","Power + runtime orchestration"],"image":"assets/screenshots/pfc-power-management-v6.png","imageAlt":"PFC power management dashboard","imageCaption":"Power Management command center.","imageFit":"contain","gallery":[{"src":"assets/screenshots/pfc-power-management-v6.png","alt":"PFC power management dashboard","title":"Power management","copy":"Power policy, workload attribution, schedule protection, and estimated savings are visible in one control surface.","kind":"screenshot","orientation":"portrait"},{"src":"assets/screenshots/pfc-energy-ledger-v6.png","alt":"PFC energy ledger","title":"Energy ledger","copy":"Observed sleep history is kept separate from modeled avoided energy and projected cost savings.","kind":"screenshot","orientation":"portrait"},{"src":"assets/screenshots/pfc-ai-runtime-v6.png","alt":"PFC AI runtime reconciliation page","title":"Runtime reconciliation","copy":"Model endpoints are checked after wake for process state, model identity, and required GPU offload.","kind":"screenshot","orientation":"portrait"},{"src":"assets/screenshots/pfc-eligibility-matrix-v6.png","alt":"PFC subsystem eligibility matrix","title":"Suspend safety matrix","copy":"The policy engine explains exactly which subsystem allowed or blocked a suspend decision.","kind":"screenshot","orientation":"portrait"},{"src":"assets/screenshots/pfc-top-terminal.png","alt":"PFC Top terminal interface","title":"PFC Top","copy":"A custom terminal-style interface makes compute, workloads, power policy, and energy status readable on the server display.","kind":"screenshot","orientation":"landscape"},{"src":"assets/images/pfc-top-physical.jpg","alt":"PFC Top running on the physical server display","title":"Physical monitoring","copy":"The local screen keeps server health visible even when the main web interface is not open.","orientation":"portrait"}],"metrics":[{"value":"95.0 h","label":"observed sleep"},{"value":"13.19 kWh","label":"estimated seven-day avoidance"},{"value":"$290.54/yr","label":"current projection"},{"value":"Fail-safe","label":"blocked on stale or unknown state"}],"tabs":[{"id":"overview","label":"Overview","html":"<div class=\"project-section-heading compact\"><div><p class=\"project-eyebrow\">Overview</p><h2>A control plane for an AI server that should not stay awake without a reason.</h2></div></div><div class=\"project-overview-grid\"><article><p class=\"project-eyebrow\">Power policy</p><h3>Sleep when idle, wake for work</h3><p>PFC combines host state, workloads, schedules, leases, and safety rules before allowing a suspend.</p></article><article><p class=\"project-eyebrow\">Runtime recovery</p><h3>Wake is not the end of the process</h3><p>llama.cpp endpoints are reconciled after wake so model identity and GPU offload are verified before service is accepted as healthy.</p></article></div>"},{"id":"engineering","label":"Engineering","html":"<div class=\"project-section-heading compact\"><div><p class=\"project-eyebrow\">Engineering</p><h2>The system favors explainable, reversible state changes.</h2></div></div><div class=\"project-decision-grid compact-decisions\"><article class=\"project-decision\"><span>01</span><div><h3>Treat unknown as unsafe</h3><p>Stale or missing telemetry blocks automatic suspend instead of being guessed away.</p></div></article><article class=\"project-decision\"><span>02</span><div><h3>Protect scheduled work</h3><p>Hermes schedules stay cached on the low-power Pi so the server can still wake for future jobs.</p></div></article><article class=\"project-decision\"><span>03</span><div><h3>Separate recommendation from policy</h3><p>Predicted sleep or wake windows remain advisory until explicitly saved.</p></div></article></div>"},{"id":"savings","label":"Power Savings","html":"<div class=\"project-section-heading compact\"><div><p class=\"project-eyebrow\">Power savings</p><h2>The current snapshot records 95 hours of sleep</h2></div></div><div class=\"savings-kpi-grid\"><article><strong>95.0 h</strong><span>observed sleep history</span></article><article><strong>13.19 kWh</strong><span>estimated avoided energy over seven days</span></article><article><strong>2.27 kWh/day</strong><span>average estimated savings</span></article><article><strong>68.23 kWh</strong><span>projected over 30 days</span></article><article><strong>$290.54/yr</strong><span>current projected annual value</span></article></div><p class=\"project-caveat\"><strong>Measurement note:</strong> sleep duration is retained from system-state history. Avoided energy and dollar values are modeled from configured power baselines until direct host metering is available.</p>"},{"id":"documentation","label":"Documentation","html":"<div class=\"project-section-heading compact\"><div><p class=\"project-eyebrow\">Documentation</p><h2>The web control plane and the physical server display.</h2></div></div><div class=\"project-gallery documentation-carousel gallery-count-6\"><figure class=\"screenshot portrait\"><button type=\"button\" data-lightbox data-caption=\"Power management — Power policy, workload attribution, schedule protection, and estimated savings are visible in one control surface.\"><img loading=\"lazy\" src=\"assets/screenshots/pfc-power-management-v6.png\" alt=\"PFC power management dashboard\"></button><figcaption><strong>Power management</strong>Power policy, workload attribution, schedule protection, and estimated savings are visible in one control surface.</figcaption></figure><figure class=\"screenshot portrait\"><button type=\"button\" data-lightbox data-caption=\"Energy ledger — Observed sleep history is kept separate from modeled avoided energy and projected cost savings.\"><img loading=\"lazy\" src=\"assets/screenshots/pfc-energy-ledger-v6.png\" alt=\"PFC energy ledger\"></button><figcaption><strong>Energy ledger</strong>Observed sleep history is kept separate from modeled avoided energy and projected cost savings.</figcaption></figure><figure class=\"screenshot portrait\"><button type=\"button\" data-lightbox data-caption=\"Runtime reconciliation — Model endpoints are checked after wake for process state, model identity, and required GPU offload.\"><img loading=\"lazy\" src=\"assets/screenshots/pfc-ai-runtime-v6.png\" alt=\"PFC AI runtime reconciliation page\"></button><figcaption><strong>Runtime reconciliation</strong>Model endpoints are checked after wake for process state, model identity, and required GPU offload.</figcaption></figure><figure class=\"screenshot portrait\"><button type=\"button\" data-lightbox data-caption=\"Suspend safety matrix — The policy engine explains exactly which subsystem allowed or blocked a suspend decision.\"><img loading=\"lazy\" src=\"assets/screenshots/pfc-eligibility-matrix-v6.png\" alt=\"PFC subsystem eligibility matrix\"></button><figcaption><strong>Suspend safety matrix</strong>The policy engine explains exactly which subsystem allowed or blocked a suspend decision.</figcaption></figure><figure class=\"screenshot landscape\"><button type=\"button\" data-lightbox data-caption=\"PFC Top — A custom terminal-style interface makes compute, workloads, power policy, and energy status readable on the server display.\"><img loading=\"lazy\" src=\"assets/screenshots/pfc-top-terminal.png\" alt=\"PFC Top terminal interface\"></button><figcaption><strong>PFC Top</strong>A custom terminal-style interface makes compute, workloads, power policy, and energy status readable on the server display.</figcaption></figure><figure class=\"portrait\"><button type=\"button\" data-lightbox data-caption=\"Physical monitoring — The local screen keeps server health visible even when the main web interface is not open.\"><img loading=\"lazy\" src=\"assets/images/pfc-top-physical.jpg\" alt=\"PFC Top running on the physical server display\"></button><figcaption><strong>Physical monitoring</strong>The local screen keeps server health visible even when the main web interface is not open.</figcaption></figure></div>"},{"id":"minecraft","label":"Access Control","html":"<div class=\"project-section-heading compact\"><div><p class=\"project-eyebrow\">Access control</p><h2>A separate Minecraft surface demonstrates safe delegation</h2></div></div><div class=\"project-overview-grid\"><article><p class=\"project-eyebrow\">Launcher</p><h3>In-house and AI-assisted</h3><p>Automatic installation and updates reduce support work for the private server.</p></article><article><p class=\"project-eyebrow\">Permissions</p><h3>Friends only see Minecraft controls</h3><p>Moderator and player access is separated from AI-runtime and power-administration functions.</p></article><article><p class=\"project-eyebrow\">Network</p><h3>Tailscale and reverse proxying</h3><p>Remote access is designed around identity, limited scope, and private infrastructure rather than exposing the control plane directly.</p></article></div>"},{"id":"results","label":"Results","html":"<div class=\"project-section-heading compact\"><div><p class=\"project-eyebrow\">Results</p><h2>PFC reduced idle runtime while keeping scheduled and active work protected.</h2></div></div><div class=\"project-outcome-grid compact-outcomes\"><article><span>01</span><h3>Measured sleep history</h3><p>Wake and sleep transitions are retained rather than inferred from missing power samples.</p></article><article><span>02</span><h3>Inspectable policy</h3><p>Every suspend decision can be traced to explicit subsystem states and blockers.</p></article><article><span>03</span><h3>Operational continuity</h3><p>PFC Top, cached schedules, and runtime reconciliation keep the system understandable across sleep/wake cycles.</p></article></div>"},{"id":"future","label":"Future Work","html":"<div class=\"project-section-heading compact\"><div><p class=\"project-eyebrow\">Current R&amp;D</p><h2>Improve measurement accuracy and infrastructure recovery.</h2></div></div><div class=\"project-flow compact-flow\"><article><span>01</span><h3>Direct host metering</h3><p>Replace modeled host load with a dedicated metering source where practical.</p></article><article><span>02</span><h3>Cross-machine diagnosis</h3><p>Let a Hermes agent on the workstation and server help inspect one another when either side is unavailable.</p></article><article><span>03</span><h3>Longer retained history</h3><p>Build a larger measured dataset before relying on long-range projections or schedule recommendations.</p></article></div>"},{"id":"references","label":"References","html":"<div class=\"project-section-heading compact\"><div><p class=\"project-eyebrow\">References</p><h2>Upstream projects and technical references</h2></div></div><div class=\"reference-callout\"><p>PFC is Joseph&#x27;s private supervisory application. It manages local services built on established infrastructure components.</p><p><strong>My work:</strong> Power policy, energy ledger, schedule cache, wake/suspend safety matrix, runtime reconciliation, PFC Top, access-control surfaces, and integrated operational UI.</p><div class=\"project-reference-list\"><a class=\"project-reference-chip\" href=\"https://github.com/ggml-org/llama.cpp\" rel=\"noreferrer\" target=\"_blank\">llama.cpp <span>↗</span></a><a class=\"project-reference-chip\" href=\"https://hermes-agent.nousresearch.com/docs/\" rel=\"noreferrer\" target=\"_blank\">Hermes Agent docs <span>↗</span></a><a class=\"project-reference-chip\" href=\"https://tailscale.com/kb\" rel=\"noreferrer\" target=\"_blank\">Tailscale docs <span>↗</span></a></div></div>"}],"next":"Add direct host metering and validate cross-machine recovery before expanding autonomous policy changes.","fallbackPage":"projects/pfc-supervisor/"},"hermes":{"id":"hermes","tone":"orange","eyebrow":"Local agent and automation layer","title":"Hermes automation stack","lede":"A locally hosted Hermes Agent deployment configured to route work between llama.cpp models, PFC, Print Orchestrator, desktop tools, Discord, and scheduled automations.","status":["Active","Built on Nous Research Hermes","Local-first automation"],"image":"assets/screenshots/pfc-pulse.png","imageAlt":"PFC Pulse desktop voice companion","imageCaption":"PFC Pulse voice companion on the main workstation.","imageFit":"contain","gallery":[{"src":"assets/screenshots/pfc-pulse.png","alt":"PFC Pulse desktop voice companion","title":"PFC Pulse","copy":"A push-to-talk desktop companion uses Whisper speech recognition and Piper speech output around Hermes voice control.","kind":"screenshot","orientation":"portrait"},{"src":"assets/screenshots/pfc-command.png","alt":"PFC Command compact desktop widget","title":"PFC Command","copy":"The compact widget exposes server state, workloads, and limited power actions without opening the full control plane.","kind":"screenshot","orientation":"portrait"},{"src":"assets/images/pi-case-render.png","alt":"OpenSCAD Raspberry Pi enclosure output","title":"Prompt-to-CAD output","copy":"A Pi enclosure demonstrates the type of parametric output being developed for the Hermes-to-Print-Orchestrator workflow.","orientation":"landscape"},{"src":"assets/screenshots/pfc-top-terminal.png","alt":"PFC Top terminal data available to Hermes integrations","title":"Shared operations data","copy":"PFC, printer, power, and runtime data form the operational context used by the automation layer.","kind":"screenshot","orientation":"landscape"}],"metrics":[{"value":"2 roles","label":"manager + worker routing"},{"value":"Whisper","label":"speech recognition"},{"value":"Piper","label":"speech output"},{"value":"Cross-system","label":"PFC + printers + desktop"}],"tabs":[{"id":"overview","label":"Overview","html":"<div class=\"project-section-heading compact\"><div><p class=\"project-eyebrow\">Overview</p><h2>The agent layer connecting local models to physical and operational systems.</h2></div></div><div class=\"project-overview-grid\"><article><p class=\"project-eyebrow\">Inference</p><h3>Local llama.cpp endpoints</h3><p>Muse handles manager duties while Qwen3.6 handles high-throughput tool and implementation work.</p></article><article><p class=\"project-eyebrow\">Automation</p><h3>Tools remain behind explicit interfaces</h3><p>Hermes acts through PFC and Print Orchestrator instead of receiving unrestricted access to every service.</p></article></div>"},{"id":"integrations","label":"Integrations","html":"<div class=\"project-section-heading compact\"><div><p class=\"project-eyebrow\">Integrations</p><h2>Hermes links local inference to the tools that operate the lab</h2></div></div><div class=\"hermes-integration-map\"><article><span>01</span><h3>Print Orchestrator</h3><p>CAD, slicing, dispatch, printer state, power, and failure warnings.</p></article><article><span>02</span><h3>PFC</h3><p>Runtime state, schedule protection, energy policy, and server recovery.</p></article><article><span>03</span><h3>Desktop</h3><p>PFC Pulse, PFC Command, voice input, and limited control surfaces.</p></article><article><span>04</span><h3>Discord</h3><p>Notifications, scheduled outputs, planned meeting summaries, and action-item delivery.</p></article></div>"},{"id":"documentation","label":"Documentation","html":"<div class=\"project-section-heading compact\"><div><p class=\"project-eyebrow\">Documentation</p><h2>Desktop controls and shared automation outputs.</h2></div></div><div class=\"project-gallery documentation-carousel gallery-count-4\"><figure class=\"screenshot portrait\"><button type=\"button\" data-lightbox data-caption=\"PFC Pulse — A push-to-talk desktop companion uses Whisper speech recognition and Piper speech output around Hermes voice control.\"><img loading=\"lazy\" src=\"assets/screenshots/pfc-pulse.png\" alt=\"PFC Pulse desktop voice companion\"></button><figcaption><strong>PFC Pulse</strong>A push-to-talk desktop companion uses Whisper speech recognition and Piper speech output around Hermes voice control.</figcaption></figure><figure class=\"screenshot portrait\"><button type=\"button\" data-lightbox data-caption=\"PFC Command — The compact widget exposes server state, workloads, and limited power actions without opening the full control plane.\"><img loading=\"lazy\" src=\"assets/screenshots/pfc-command.png\" alt=\"PFC Command compact desktop widget\"></button><figcaption><strong>PFC Command</strong>The compact widget exposes server state, workloads, and limited power actions without opening the full control plane.</figcaption></figure><figure class=\"landscape\"><button type=\"button\" data-lightbox data-caption=\"Prompt-to-CAD output — A Pi enclosure demonstrates the type of parametric output being developed for the Hermes-to-Print-Orchestrator workflow.\"><img loading=\"lazy\" src=\"assets/images/pi-case-render.png\" alt=\"OpenSCAD Raspberry Pi enclosure output\"></button><figcaption><strong>Prompt-to-CAD output</strong>A Pi enclosure demonstrates the type of parametric output being developed for the Hermes-to-Print-Orchestrator workflow.</figcaption></figure><figure class=\"screenshot landscape\"><button type=\"button\" data-lightbox data-caption=\"Shared operations data — PFC, printer, power, and runtime data form the operational context used by the automation layer.\"><img loading=\"lazy\" src=\"assets/screenshots/pfc-top-terminal.png\" alt=\"PFC Top terminal data available to Hermes integrations\"></button><figcaption><strong>Shared operations data</strong>PFC, printer, power, and runtime data form the operational context used by the automation layer.</figcaption></figure></div>"},{"id":"meetings","label":"Meeting R&D","html":"<div class=\"project-section-heading compact\"><div><p class=\"project-eyebrow\">Meeting automation</p><h2>Reduce administrative overhead in engineering meetings</h2></div></div><div class=\"project-flow compact-flow\"><article><span>01</span><h3>Capture</h3><p>Transcribe Discord or in-person audio and identify speakers where the source supports it.</p></article><article><span>02</span><h3>Understand</h3><p>Translate when needed, summarize the discussion, and extract decisions and action items.</p></article><article><span>03</span><h3>Organize</h3><p>Prepare calendar entries, deadlines, and follow-up notes for review before saving.</p></article><article><span>04</span><h3>Deliver</h3><p>Publish a concise record to Discord or another approved destination.</p></article></div><p class=\"project-caveat\"><strong>Status:</strong> active R&amp;D. These workflows are not presented as finished production features.</p>"},{"id":"engineering","label":"Engineering","html":"<div class=\"project-section-heading compact\"><div><p class=\"project-eyebrow\">Engineering</p><h2>AI assistance is useful only when the boundaries remain clear.</h2></div></div><div class=\"project-decision-grid compact-decisions\"><article class=\"project-decision\"><span>01</span><div><h3>Separate manager and worker roles</h3><p>Model choice is based on scope control, recovery, coding, tool use, and throughput rather than one general score.</p></div></article><article class=\"project-decision\"><span>02</span><div><h3>Keep control surfaces narrow</h3><p>PFC Command and project APIs expose the actions a workflow needs without exposing the entire infrastructure.</p></div></article><article class=\"project-decision\"><span>03</span><div><h3>Verify AI-generated work</h3><p>Hermes and ChatGPT accelerate implementation and troubleshooting, while architecture, testing, and final decisions remain human-owned.</p></div></article></div>"},{"id":"future","label":"Future Work","html":"<div class=\"project-section-heading compact\"><div><p class=\"project-eyebrow\">Current R&amp;D</p><h2>Make the automation layer more durable and useful in engineering workflows.</h2></div></div><div class=\"project-flow compact-flow\"><article><span>01</span><h3>Cross-machine recovery agent</h3><p>Connect the workstation and server so each can help inspect the other during an outage.</p></article><article><span>02</span><h3>Production model evaluation</h3><p>Continue role-specific tests for manager and worker duties as models and llama.cpp builds change.</p></article><article><span>03</span><h3>Meeting assistant</h3><p>Validate transcription, translation, summarization, calendars, and action-item extraction with review gates.</p></article></div>"},{"id":"references","label":"References","html":"<div class=\"project-section-heading compact\"><div><p class=\"project-eyebrow\">References</p><h2>Upstream projects and technical references</h2></div></div><div class=\"reference-callout\"><p>Hermes Agent is the upstream Nous Research platform. My work covers local deployment, model routing, tools, voice interfaces, schedules, and integrations with PFC and Print Orchestrator.</p><p><strong>My work:</strong> Local model routing, llama.cpp endpoints, PFC/Print-Orchestrator integrations, PFC Pulse, PFC Command, scheduled workflows, and ongoing recovery/meeting automation development.</p><div class=\"project-reference-list\"><a class=\"project-reference-chip\" href=\"https://hermes-agent.nousresearch.com/docs/\" rel=\"noreferrer\" target=\"_blank\">Hermes Agent docs <span>↗</span></a><a class=\"project-reference-chip\" href=\"https://github.com/ggml-org/llama.cpp\" rel=\"noreferrer\" target=\"_blank\">llama.cpp <span>↗</span></a><a class=\"project-reference-chip\" href=\"https://openscad.org/documentation\" rel=\"noreferrer\" target=\"_blank\">OpenSCAD docs <span>↗</span></a></div></div>"}],"next":"Validate the cross-machine recovery design and meeting workflows before treating them as operational services.","fallbackPage":"projects/hermes/"},"ai-server":{"id":"ai-server","tone":"orange","eyebrow":"Local AI infrastructure","title":"B70 / PFP local AI server","lede":"A custom local-inference platform built around llama.cpp, SYCL, role-specific model testing, production service profiles, and integration with Hermes and PFC.","status":["Active","llama.cpp inference","Manager + worker services"],"image":"assets/images/pfp-server-pi-case.jpg","imageAlt":"Custom B70 PFP server with Raspberry Pi enclosure and display","imageCaption":"Custom B70/PFP server with local control node and display.","imageFit":"contain","gallery":[{"src":"assets/images/pfp-server-pi-case.jpg","alt":"Custom B70 PFP server with Raspberry Pi enclosure and display","title":"B70 / PFP system","copy":"The physical server hosts local inference, orchestration services, power controls, and the local monitoring display.","orientation":"portrait"},{"src":"assets/images/ai-img-8916.jpg","alt":"Open B70 server chassis","title":"Hardware integration","copy":"Compute, cooling, power, storage, and service access were packaged into a custom enclosure.","orientation":"portrait"},{"src":"assets/images/ai-img-8931.jpg","alt":"B70 server display and enclosure","title":"Operational system","copy":"The platform is used for daily inference and engineering tools rather than benchmark-only testing.","orientation":"portrait"},{"src":"assets/screenshots/pfc-ai-runtime-v6.png","alt":"PFC AI runtime page showing local model services","title":"Runtime operations","copy":"llama.cpp services are monitored and reconciled through PFC after power-state changes.","kind":"screenshot","orientation":"portrait"}],"metrics":[{"value":"29.2 tok/s","label":"Muse manager with DFlash"},{"value":"68–71 tok/s","label":"Qwen3.6 worker native"},{"value":"131K","label":"production context"},{"value":"llama.cpp","label":"preferred inference engine"}],"tabs":[{"id":"overview","label":"Overview","html":"<div class=\"project-section-heading compact\"><div><p class=\"project-eyebrow\">Overview</p><h2>Local inference as an engineering platform rather than a single benchmark.</h2></div></div><div class=\"project-overview-grid\"><article><p class=\"project-eyebrow\">Hardware</p><h3>Custom B70 / PFP system</h3><p>The server combines compute, cooling, power, storage, local display, and service access in one working platform.</p></article><article><p class=\"project-eyebrow\">Software</p><h3>llama.cpp is the inference layer</h3><p>Deployment, model selection, quantization, KV strategy, context, GPU offload, templates, routing, and recovery are tuned around the upstream engine.</p></article></div>"},{"id":"production","label":"Production Profiles","html":"<div class=\"project-section-heading compact\"><div><p class=\"project-eyebrow\">Production profiles</p><h2>The configurations actually serving Hermes</h2></div></div><div class=\"production-profile-grid\"><article class=\"production-profile manager\"><span>MANAGER</span><h3>Muse-Glimmer 30B Q5_K_XL</h3><p>llama.cpp / SYCL · 131K context · Q8_0 KV · medium reasoning · DFlash n2 / p-min 0.30</p><div><strong>29.2 tok/s</strong><small>~71.2% draft acceptance</small></div><ul><li>~21.4 tok/s native</li><li>~36% selected improvement</li><li>Higher-speed low-reasoning tests made more mistakes</li></ul></article><article class=\"production-profile worker\"><span>WORKER</span><h3>Qwen3.6 35B-A3B Q5_K_XL</h3><p>llama.cpp / SYCL · 131K context · q4_1 KV · custom Jinja tool template · native decode</p><div><strong>68–71 tok/s</strong><small>MTP tested and rejected</small></div><ul><li>Q5_K_S reached ~72.9 tok/s in testing</li><li>Q5_K_XL remains the selected production worker</li><li>Production script differs from the simpler router preset</li></ul></article></div><div class=\"data-downloads\"><a href=\"assets/downloads/production-model-profiles-2026-08-15.csv\" download>Download profile summary CSV ↓</a></div>"},{"id":"benchmarks","label":"Full Benchmarks","html":"<div class=\"project-section-heading compact\"><div><p class=\"project-eyebrow\">Standardized llama-bench</p><h2>Full model throughput library</h2></div></div><p class=\"benchmark-method\">SYCL backend · pp512 + tg128 · 3 repetitions · <code>-ngl 99</code> · llama.cpp build 10369. A llama-server process warning was present during the chosen reference sweep, so these values remain the normal comparison set rather than a laboratory-isolated claim.</p><div class=\"benchmark-table-wrap\"><table class=\"benchmark-table compact-benchmark\"><thead><tr><th>Model</th><th>Quant</th><th>pp512 tok/s</th><th>tg128 tok/s</th></tr></thead><tbody><tr><td>Gemma 4 E2B</td><td>Q4_K_XL</td><td>5315.26 ± 96.11</td><td>136.58 ± 0.12</td></tr><tr><td>Gemma 4 E4B</td><td>Q4_K_XL</td><td>3165.46 ± 64.46</td><td>88.48 ± 0.39</td></tr><tr><td>Gemma 4 12B</td><td>Q4_K_XL</td><td>1511.79 ± 3.94</td><td>49.04 ± 0.26</td></tr><tr><td>Gemma 4 26B-A4B</td><td>Q4_K_M</td><td>772.25 ± 86.10</td><td>66.89 ± 8.71</td></tr><tr><td>Qwen3.6 35B-A3B</td><td>Q5_K_XL</td><td>724.97 ± 68.36</td><td>75.63 ± 1.19</td></tr><tr><td>Qwen3.6 35B-A3B</td><td>Q5_K_S</td><td>724.90 ± 68.10</td><td>72.77 ± 3.28</td></tr><tr><td>Qwen3.6 35B-A3B</td><td>Q4_K_M</td><td>706.68 ± 97.73</td><td>77.52 ± 1.98</td></tr><tr><td>Muse-Glimmer 30B</td><td>Q5_K_XL</td><td>569.33 ± 77.41</td><td>22.00 ± 0.02</td></tr><tr><td>Kanana 2 30B-A3B</td><td>Q4_K_M</td><td>593.42 ± 37.51</td><td>28.18 ± 0.08</td></tr><tr><td>Qwen 3.8 27B</td><td>Q6_K</td><td>485.92 ± 80.05</td><td>19.92 ± 0.03</td></tr><tr><td>Gemma 4 31B</td><td>Q4_K_XL</td><td>427.72 ± 16.36</td><td>22.62 ± 0.07</td></tr><tr><td>Qwen3.5 0.8B</td><td>Q8_K_XL</td><td>14262.06 ± 1417.45</td><td>202.79 ± 0.35</td></tr></tbody></table></div><div class=\"data-downloads\"><a href=\"assets/downloads/b70-standardized-llama-bench-2026-08-14.csv\" download>Download standardized CSV ↓</a></div>"},{"id":"mtp","label":"MTP Sweep","html":"<div class=\"project-section-heading compact\"><div><p class=\"project-eyebrow\">Broad MTP sweep</p><h2>Speculative decoding helped some models and hurt others</h2></div></div><div class=\"benchmark-table-wrap\"><table class=\"benchmark-table compact-benchmark\"><thead><tr><th>Model</th><th>Baseline</th><th>Best mode</th><th>Best decode</th><th>Acceptance</th><th>Speedup</th></tr></thead><tbody><tr><td>Gemma 4 12B</td><td>47.863</td><td>n2</td><td>71.555</td><td>76.35%</td><td>1.495×</td></tr><tr><td>Gemma 4 26B-A4B</td><td>75.318</td><td>n4</td><td>93.331</td><td>63.61%</td><td>1.239×</td></tr><tr><td>Gemma 4 31B</td><td>22.100</td><td>n2</td><td>33.060</td><td>81.44%</td><td>1.496×</td></tr><tr><td>Qwen3.6 35B-A3B Q5_K_S</td><td>77.153</td><td>baseline</td><td>77.153</td><td>—</td><td>1.000×</td></tr><tr><td>Qwen 3.8 27B</td><td>19.870</td><td>n2</td><td>33.196</td><td>70.70%</td><td>1.671×</td></tr></tbody></table></div><p class=\"project-caveat\">n2 was usually the useful setting, n4 won for Gemma 26B-A4B, n8 was consistently harmful, and Qwen3.6 was faster without MTP. Baseline-only rows in the source file are labeled as not measured in this sweep rather than unsupported.</p><div class=\"data-downloads\"><a href=\"assets/downloads/mtp-broad-sweep-2026-08-14.csv\" download>Download broad sweep CSV ↓</a></div>"},{"id":"documentation","label":"Documentation","html":"<div class=\"project-section-heading compact\"><div><p class=\"project-eyebrow\">Documentation</p><h2>Physical hardware and the runtime control surface.</h2></div></div><div class=\"project-gallery documentation-carousel gallery-count-4\"><figure class=\"portrait\"><button type=\"button\" data-lightbox data-caption=\"B70 / PFP system — The physical server hosts local inference, orchestration services, power controls, and the local monitoring display.\"><img loading=\"lazy\" src=\"assets/images/pfp-server-pi-case.jpg\" alt=\"Custom B70 PFP server with Raspberry Pi enclosure and display\"></button><figcaption><strong>B70 / PFP system</strong>The physical server hosts local inference, orchestration services, power controls, and the local monitoring display.</figcaption></figure><figure class=\"portrait\"><button type=\"button\" data-lightbox data-caption=\"Hardware integration — Compute, cooling, power, storage, and service access were packaged into a custom enclosure.\"><img loading=\"lazy\" src=\"assets/images/ai-img-8916.jpg\" alt=\"Open B70 server chassis\"></button><figcaption><strong>Hardware integration</strong>Compute, cooling, power, storage, and service access were packaged into a custom enclosure.</figcaption></figure><figure class=\"portrait\"><button type=\"button\" data-lightbox data-caption=\"Operational system — The platform is used for daily inference and engineering tools rather than benchmark-only testing.\"><img loading=\"lazy\" src=\"assets/images/ai-img-8931.jpg\" alt=\"B70 server display and enclosure\"></button><figcaption><strong>Operational system</strong>The platform is used for daily inference and engineering tools rather than benchmark-only testing.</figcaption></figure><figure class=\"screenshot portrait\"><button type=\"button\" data-lightbox data-caption=\"Runtime operations — llama.cpp services are monitored and reconciled through PFC after power-state changes.\"><img loading=\"lazy\" src=\"assets/screenshots/pfc-ai-runtime-v6.png\" alt=\"PFC AI runtime page showing local model services\"></button><figcaption><strong>Runtime operations</strong>llama.cpp services are monitored and reconciled through PFC after power-state changes.</figcaption></figure></div>"},{"id":"engineering","label":"Engineering","html":"<div class=\"project-section-heading compact\"><div><p class=\"project-eyebrow\">Engineering</p><h2>Models enter production only after role-specific testing.</h2></div></div><div class=\"project-decision-grid compact-decisions\"><article class=\"project-decision\"><span>01</span><div><h3>Benchmark methods separately</h3><p>Standard llama-bench, end-to-end decode, and speculative-decoding studies are not mixed into one ranking.</p></div></article><article class=\"project-decision\"><span>02</span><div><h3>Select for the role</h3><p>Manager tests emphasize scope, delegation, and recovery; worker tests emphasize coding, tool use, debugging, and throughput.</p></div></article><article class=\"project-decision\"><span>03</span><div><h3>Keep deployed profiles explicit</h3><p>The selected Muse and Qwen startup settings are treated separately from router presets and research configurations.</p></div></article></div>"},{"id":"results","label":"Results","html":"<div class=\"project-section-heading compact\"><div><p class=\"project-eyebrow\">Results</p><h2>The system now has measured, role-specific production choices.</h2></div></div><div class=\"project-outcome-grid compact-outcomes\"><article><span>01</span><h3>Faster manager</h3><p>DFlash raises selected Muse generation from about 21.4 to 29.2 tok/s at roughly 71% acceptance.</p></article><article><span>02</span><h3>Fast native worker</h3><p>Qwen3.6 serves tool and implementation work at about 68–71 tok/s without speculative overhead.</p></article><article><span>03</span><h3>Traceable research</h3><p>Standardized throughput, broad MTP tests, and active production profiles remain separate and downloadable.</p></article></div>"},{"id":"references","label":"References","html":"<div class=\"project-section-heading compact\"><div><p class=\"project-eyebrow\">References</p><h2>Upstream projects and technical references</h2></div></div><div class=\"reference-callout\"><p>llama.cpp is the upstream local-inference engine used throughout the system.</p><p><strong>My work:</strong> Hardware integration, SYCL deployment, containers, model/quant selection, KV/cache tuning, speculative-decoding experiments, custom tool templates, benchmarks, service startup, PFC recovery, and Hermes routing.</p><div class=\"project-reference-list\"><a class=\"project-reference-chip\" href=\"https://github.com/ggml-org/llama.cpp\" rel=\"noreferrer\" target=\"_blank\">llama.cpp <span>↗</span></a><a class=\"project-reference-chip\" href=\"https://hermes-agent.nousresearch.com/docs/\" rel=\"noreferrer\" target=\"_blank\">Hermes Agent docs <span>↗</span></a></div></div>"}],"next":"Refresh the standardized sweep with the next model set while preserving older rows as explicitly labeled historical data.","fallbackPage":"projects/ai-server/"},"e3ng":{"id":"e3ng","tone":"orange","eyebrow":"CoreXY conversion","title":"E3NG CoreXY conversion","lede":"An Ender 3 platform rebuilt into a custom CoreXY machine with Klipper, networked electronics, sensing, and a measured commissioning workflow.","status":["Working machine","CoreXY + Klipper","Custom integration"],"image":"assets/images/e3ng-full-printer.jpg","imageAlt":"Complete E3NG CoreXY conversion","imageCaption":"Complete E3NG conversion.","imageFit":"contain","gallery":[{"src":"assets/images/e3ng-full-printer.jpg","alt":"Complete E3NG CoreXY conversion","title":"Complete machine","copy":"The converted Ender platform is operating as a custom CoreXY printer with Klipper and networked control electronics.","orientation":"portrait"},{"src":"assets/images/e3ng-img-7200-1.jpg","alt":"E3NG toolhead probe and wiring","title":"Toolhead sensing","copy":"Probe integration and compact wiring support repeatable bed measurement and serviceability.","orientation":"portrait"},{"src":"assets/images/e3ng-img-7128-1.jpg","alt":"E3NG controller and Raspberry Pi electronics","title":"Control hardware","copy":"The controller, Raspberry Pi, networking, and toolhead electronics are integrated as one motion platform.","orientation":"portrait"},{"src":"assets/images/e3ng-img-7150-1.jpg","alt":"E3NG Klipper bed mesh heightmap","title":"Measured calibration","copy":"Bed-mesh and input-shaper data guide tuning instead of visual guesswork.","orientation":"portrait"}],"metrics":[{"value":"CoreXY","label":"motion conversion"},{"value":"Klipper","label":"firmware and tuning"},{"value":"CAN-style","label":"toolhead networking"},{"value":"Measured","label":"mesh and resonance tuning"}],"tabs":[{"id":"overview","label":"Overview","html":"<div class=\"project-section-heading compact\"><div><p class=\"project-eyebrow\">Overview</p><h2>A printer rebuild that became a complete controls project.</h2></div></div><div class=\"project-overview-grid\"><article><p class=\"project-eyebrow\">Mechanical</p><h3>CoreXY frame and motion</h3><p>The conversion required frame alignment, belt routing, gantry setup, toolhead packaging, and a complete rebuild of the motion system.</p></article><article><p class=\"project-eyebrow\">Controls</p><h3>Firmware, sensing, and networks</h3><p>Klipper, the Raspberry Pi, controller, probe, toolhead electronics, and calibration data were commissioned together.</p></article></div>"},{"id":"engineering","label":"Engineering","html":"<div class=\"project-section-heading compact\"><div><p class=\"project-eyebrow\">Engineering</p><h2>Mechanical accuracy came before software compensation.</h2></div></div><div class=\"project-decision-grid compact-decisions\"><article class=\"project-decision\"><span>01</span><div><h3>Square the machine first</h3><p>Frame, belt, and gantry errors were addressed before relying on firmware compensation.</p></div></article><article class=\"project-decision\"><span>02</span><div><h3>Use measured tuning</h3><p>Bed mesh and resonance data guided configuration changes.</p></div></article><article class=\"project-decision\"><span>03</span><div><h3>Keep electronics serviceable</h3><p>Controllers, networking, wiring, and toolhead connections remain reachable for diagnosis.</p></div></article></div>"},{"id":"documentation","label":"Documentation","html":"<div class=\"project-section-heading compact\"><div><p class=\"project-eyebrow\">Documentation</p><h2>The complete machine, electronics, toolhead, and calibration output.</h2></div></div><div class=\"project-gallery documentation-carousel gallery-count-4\"><figure class=\"portrait\"><button type=\"button\" data-lightbox data-caption=\"Complete machine — The converted Ender platform is operating as a custom CoreXY printer with Klipper and networked control electronics.\"><img loading=\"lazy\" src=\"assets/images/e3ng-full-printer.jpg\" alt=\"Complete E3NG CoreXY conversion\"></button><figcaption><strong>Complete machine</strong>The converted Ender platform is operating as a custom CoreXY printer with Klipper and networked control electronics.</figcaption></figure><figure class=\"portrait\"><button type=\"button\" data-lightbox data-caption=\"Toolhead sensing — Probe integration and compact wiring support repeatable bed measurement and serviceability.\"><img loading=\"lazy\" src=\"assets/images/e3ng-img-7200-1.jpg\" alt=\"E3NG toolhead probe and wiring\"></button><figcaption><strong>Toolhead sensing</strong>Probe integration and compact wiring support repeatable bed measurement and serviceability.</figcaption></figure><figure class=\"portrait\"><button type=\"button\" data-lightbox data-caption=\"Control hardware — The controller, Raspberry Pi, networking, and toolhead electronics are integrated as one motion platform.\"><img loading=\"lazy\" src=\"assets/images/e3ng-img-7128-1.jpg\" alt=\"E3NG controller and Raspberry Pi electronics\"></button><figcaption><strong>Control hardware</strong>The controller, Raspberry Pi, networking, and toolhead electronics are integrated as one motion platform.</figcaption></figure><figure class=\"portrait\"><button type=\"button\" data-lightbox data-caption=\"Measured calibration — Bed-mesh and input-shaper data guide tuning instead of visual guesswork.\"><img loading=\"lazy\" src=\"assets/images/e3ng-img-7150-1.jpg\" alt=\"E3NG Klipper bed mesh heightmap\"></button><figcaption><strong>Measured calibration</strong>Bed-mesh and input-shaper data guide tuning instead of visual guesswork.</figcaption></figure></div>"},{"id":"results","label":"Results","html":"<div class=\"project-section-heading compact\"><div><p class=\"project-eyebrow\">Results</p><h2>The conversion became a usable custom motion platform.</h2></div></div><div class=\"project-outcome-grid compact-outcomes\"><article><span>01</span><h3>Working CoreXY machine</h3><p>The rebuilt mechanics, firmware, and sensing operate as one system.</p></article><article><span>02</span><h3>Repeatable commissioning</h3><p>Faults can be separated into mechanical, electrical, networking, and software layers.</p></article><article><span>03</span><h3>Automation experience</h3><p>The project mirrors small-scale machine commissioning and maintenance work.</p></article></div>"},{"id":"references","label":"References","html":"<div class=\"project-section-heading compact\"><div><p class=\"project-eyebrow\">References</p><h2>Upstream projects and technical references</h2></div></div><div class=\"reference-callout\"><p>E3NG is an upstream RH3D Ender 3 NG CoreXY conversion project.</p><p><strong>My work:</strong> Mechanical build, electronics integration, Raspberry Pi/controller setup, toolhead networking, Klipper configuration, sensing, commissioning, tuning, and maintenance.</p><div class=\"project-reference-list\"><a class=\"project-reference-chip\" href=\"https://github.com/RH3D/E3NG\" rel=\"noreferrer\" target=\"_blank\">RH3D E3NG <span>↗</span></a><a class=\"project-reference-chip\" href=\"https://www.klipper3d.org/\" rel=\"noreferrer\" target=\"_blank\">Klipper docs <span>↗</span></a></div></div>"}],"next":"Continue enclosure, thermal, and material-profile work while documenting repeatability over longer production use.","fallbackPage":"projects/e3ng/"},"voron-systems":{"id":"voron-systems","tone":"orange","eyebrow":"Enclosed CoreXY system","title":"Voron 2.4","lede":"An enclosed CoreXY printer commissioned for technical materials, functional parts, calibration, maintenance, and repeatable operation.","status":["Working machine","Voron 2.4","Technical materials"],"image":"assets/images/voron-2-4-full-printer.jpg","imageAlt":"Complete enclosed Voron 2.4 printer","imageCaption":"Complete enclosed Voron 2.4.","imageFit":"contain","gallery":[{"src":"assets/images/voron-2-4-full-printer.jpg","alt":"Complete enclosed Voron 2.4 printer","title":"Complete Voron 2.4","copy":"The enclosed CoreXY system is commissioned for technical materials, functional parts, and repeatable maintenance.","orientation":"portrait"},{"src":"assets/images/voron-img-6388-1.jpg","alt":"Voron toolhead and printed components","title":"Functional printed assembly","copy":"Printed mechanical components are used to validate fit, material behavior, and machine repeatability.","orientation":"portrait"}],"metrics":[{"value":"Voron 2.4","label":"open-source platform"},{"value":"Enclosed","label":"thermal control"},{"value":"CoreXY","label":"high-speed motion"},{"value":"Technical","label":"functional materials"}],"tabs":[{"id":"overview","label":"Overview","html":"<div class=\"project-section-heading compact\"><div><p class=\"project-eyebrow\">Overview</p><h2>A printer treated as production equipment.</h2></div></div><div class=\"project-overview-grid\"><article><p class=\"project-eyebrow\">Purpose</p><h3>Functional prototyping</h3><p>The enclosed platform supports parts and materials that need controlled motion, temperature, and repeatable setup.</p></article><article><p class=\"project-eyebrow\">My work</p><h3>Build, tune, maintain</h3><p>Assembly, frame accuracy, belts, gantry alignment, electronics, toolheads, calibration, profiles, and troubleshooting are handled as one system.</p></article></div>"},{"id":"engineering","label":"Engineering","html":"<div class=\"project-section-heading compact\"><div><p class=\"project-eyebrow\">Engineering</p><h2>Reliability begins with disciplined assembly.</h2></div></div><div class=\"project-decision-grid compact-decisions\"><article class=\"project-decision\"><span>01</span><div><h3>Build square before tuning</h3><p>Frame and gantry geometry determine the limit of later calibration.</p></div></article><article class=\"project-decision\"><span>02</span><div><h3>Control the thermal process</h3><p>Enclosure behavior and material profiles are part of the mechanical system.</p></div></article><article class=\"project-decision\"><span>03</span><div><h3>Maintain for uptime</h3><p>Repeatable checks make ambiguous failures easier to isolate and repair.</p></div></article></div>"},{"id":"documentation","label":"Documentation","html":"<div class=\"project-section-heading compact\"><div><p class=\"project-eyebrow\">Documentation</p><h2>The complete machine and a functional printed assembly.</h2></div></div><div class=\"project-gallery documentation-carousel gallery-count-2\"><figure class=\"portrait\"><button type=\"button\" data-lightbox data-caption=\"Complete Voron 2.4 — The enclosed CoreXY system is commissioned for technical materials, functional parts, and repeatable maintenance.\"><img loading=\"lazy\" src=\"assets/images/voron-2-4-full-printer.jpg\" alt=\"Complete enclosed Voron 2.4 printer\"></button><figcaption><strong>Complete Voron 2.4</strong>The enclosed CoreXY system is commissioned for technical materials, functional parts, and repeatable maintenance.</figcaption></figure><figure class=\"portrait\"><button type=\"button\" data-lightbox data-caption=\"Functional printed assembly — Printed mechanical components are used to validate fit, material behavior, and machine repeatability.\"><img loading=\"lazy\" src=\"assets/images/voron-img-6388-1.jpg\" alt=\"Voron toolhead and printed components\"></button><figcaption><strong>Functional printed assembly</strong>Printed mechanical components are used to validate fit, material behavior, and machine repeatability.</figcaption></figure></div>"},{"id":"results","label":"Results","html":"<div class=\"project-section-heading compact\"><div><p class=\"project-eyebrow\">Results</p><h2>The machine supports repeatable technical work.</h2></div></div><div class=\"project-outcome-grid compact-outcomes\"><article><span>01</span><h3>Functional parts</h3><p>The system produces components for other engineering builds.</p></article><article><span>02</span><h3>Commissioning practice</h3><p>Assembly, inspection, tuning, and verification are treated as one workflow.</p></article><article><span>03</span><h3>Maintenance discipline</h3><p>Recovery and uptime are part of machine ownership rather than afterthoughts.</p></article></div>"},{"id":"references","label":"References","html":"<div class=\"project-section-heading compact\"><div><p class=\"project-eyebrow\">References</p><h2>Upstream projects and technical references</h2></div></div><div class=\"reference-callout\"><p>VORON2.4 is an upstream open-source printer platform from Voron Design.</p><p><strong>My work:</strong> Assembly, electronics integration, alignment, belts and gantry work, Klipper configuration, tuning, modifications, maintenance, and technical-material operation.</p><div class=\"project-reference-list\"><a class=\"project-reference-chip\" href=\"https://vorondesign.com/voron2.4\" rel=\"noreferrer\" target=\"_blank\">VORON2.4 <span>↗</span></a><a class=\"project-reference-chip\" href=\"https://docs.vorondesign.com/\" rel=\"noreferrer\" target=\"_blank\">Voron docs <span>↗</span></a><a class=\"project-reference-chip\" href=\"https://www.klipper3d.org/\" rel=\"noreferrer\" target=\"_blank\">Klipper docs <span>↗</span></a></div></div>"}],"next":"Add more documented technical-material parts and track the requirements each print was designed to meet.","fallbackPage":"projects/voron-systems/"},"metuned":{"id":"metuned","tone":"orange","eyebrow":"Small-business product development","title":"Metuned digital dash","lede":"A race-electronics product concept developed from an endurance-racing information gap, with work spanning enclosure design, PCB packaging, cooling, service access, branding, and product direction.","status":["Small business founder","Chief Design Officer","Prototype"],"image":"assets/images/metuned-copy-of-proto-2.jpg","imageAlt":"Metuned digital dash enclosure prototype","imageCaption":"Printed Metuned enclosure prototype.","imageFit":"cover","gallery":[{"src":"assets/images/metuned-copy-of-proto-2.jpg","alt":"Metuned digital dash enclosure prototype","title":"Enclosure prototype","copy":"The housing establishes display fit, airflow, service access, and product identity.","orientation":"landscape"},{"src":"assets/images/metuned-copy-of-proto-4-1.jpg","alt":"Metuned PCB and enclosure fitment","title":"Electronics fitment","copy":"PCB placement, connectors, wiring, and cooling were evaluated as one product package.","orientation":"landscape"}],"metrics":[{"value":"Prototype","label":"enclosure + PCB fit"},{"value":"Cooling","label":"airflow and fan packaging"},{"value":"Serviceable","label":"wiring and access"},{"value":"Founder","label":"product and business direction"}],"tabs":[{"id":"overview","label":"Overview","html":"<div class=\"project-section-heading compact\"><div><p class=\"project-eyebrow\">Overview</p><h2>A product idea built from a trackside problem.</h2></div></div><div class=\"project-overview-grid\"><article><p class=\"project-eyebrow\">Problem</p><h3>Drivers needed clearer information</h3><p>Factory instrumentation did not make the race car&#x27;s condition clear enough during endurance use.</p></article><article><p class=\"project-eyebrow\">Role</p><h3>Co-founder and Chief Design Officer</h3><p>I led the mechanical package, prototype presentation, product identity, and the connection between racing needs and a manufacturable concept.</p></article></div>"},{"id":"engineering","label":"Engineering","html":"<div class=\"project-section-heading compact\"><div><p class=\"project-eyebrow\">Engineering</p><h2>Packaging had to work inside a race car.</h2></div></div><div class=\"project-decision-grid compact-decisions\"><article class=\"project-decision\"><span>01</span><div><h3>Design around the electronics</h3><p>Display, PCB, connectors, wiring, and cooling set the enclosure geometry.</p></div></article><article class=\"project-decision\"><span>02</span><div><h3>Preserve service access</h3><p>The prototype can be opened, rewired, inspected, and repaired.</p></div></article><article class=\"project-decision\"><span>03</span><div><h3>Treat presentation as product work</h3><p>Branding and interface quality help communicate function and build trust.</p></div></article></div>"},{"id":"documentation","label":"Documentation","html":"<div class=\"project-section-heading compact\"><div><p class=\"project-eyebrow\">Documentation</p><h2>Enclosure and electronics fitment prototypes.</h2></div></div><div class=\"project-gallery documentation-carousel gallery-count-2\"><figure class=\"landscape\"><button type=\"button\" data-lightbox data-caption=\"Enclosure prototype — The housing establishes display fit, airflow, service access, and product identity.\"><img loading=\"lazy\" src=\"assets/images/metuned-copy-of-proto-2.jpg\" alt=\"Metuned digital dash enclosure prototype\"></button><figcaption><strong>Enclosure prototype</strong>The housing establishes display fit, airflow, service access, and product identity.</figcaption></figure><figure class=\"landscape\"><button type=\"button\" data-lightbox data-caption=\"Electronics fitment — PCB placement, connectors, wiring, and cooling were evaluated as one product package.\"><img loading=\"lazy\" src=\"assets/images/metuned-copy-of-proto-4-1.jpg\" alt=\"Metuned PCB and enclosure fitment\"></button><figcaption><strong>Electronics fitment</strong>PCB placement, connectors, wiring, and cooling were evaluated as one product package.</figcaption></figure></div>"},{"id":"results","label":"Results","html":"<div class=\"project-section-heading compact\"><div><p class=\"project-eyebrow\">Results</p><h2>The concept advanced from a problem statement to a physical product direction.</h2></div></div><div class=\"project-outcome-grid compact-outcomes\"><article><span>01</span><h3>Physical package</h3><p>The enclosure and electronics were evaluated together.</p></article><article><span>02</span><h3>Defined use case</h3><p>The project has a clear customer problem and development path.</p></article><article><span>03</span><h3>Founder experience</h3><p>Engineering decisions were connected to business, presentation, and customer value.</p></article></div>"}],"next":"Document the next electronics revision and show the dash operating in a vehicle when the system is ready.","fallbackPage":"projects/metuned/"},"motorsports":{"id":"motorsports","tone":"orange","eyebrow":"Leadership and fabrication","title":"Sierra College Motorsports","lede":"Student-led race preparation, fabrication, repairs, community events, sponsorship, and trackside execution around the Notta Miata Mini Cooper program.","status":["Club president","Race preparation","Community funding"],"image":"assets/images/motorsports-thebigpicture-1.jpg","imageAlt":"Sierra College Cars and Coffee event","imageCaption":"Cars and Coffee event organized to support the program.","imageFit":"cover","gallery":[{"src":"assets/images/motorsports-thebigpicture-1.jpg","alt":"Sierra College Cars and Coffee event","title":"Community event","copy":"Cars and Coffee events built visibility, recruited support, and helped fund the motorsports program.","orientation":"landscape"},{"src":"assets/images/motorsports-img-5023-2.jpg","alt":"Fabricated motorsports component","title":"Track-driven fabrication","copy":"Repairs and brackets were developed around packaging, schedule, safety, and service constraints.","orientation":"portrait"}],"metrics":[{"value":"$500","label":"starting Mini Cooper"},{"value":"3 roles","label":"treasurer → VP → president"},{"value":"Lemons","label":"endurance-racing program"},{"value":"Team-led","label":"funding, repair, execution"}],"tabs":[{"id":"overview","label":"Overview","html":"<div class=\"project-section-heading compact\"><div><p class=\"project-eyebrow\">Overview</p><h2>A race program built under budget, schedule, and reliability constraints.</h2></div></div><div class=\"project-overview-grid\"><article><p class=\"project-eyebrow\">Vehicle</p><h3>Notta Miata Mini Cooper</h3><p>The student team rebuilt and developed a low-cost car for endurance racing.</p></article><article><p class=\"project-eyebrow\">Leadership</p><h3>Move the program forward</h3><p>I helped organize planning, funding, recruitment, sponsorship, events, race preparation, and trackside work.</p></article></div>"},{"id":"engineering","label":"Engineering","html":"<div class=\"project-section-heading compact\"><div><p class=\"project-eyebrow\">Engineering</p><h2>Trackside work rewards practical decisions.</h2></div></div><div class=\"project-decision-grid compact-decisions\"><article class=\"project-decision\"><span>01</span><div><h3>Design for service</h3><p>Repairs must account for packaging, access, fasteners, and the time available.</p></div></article><article class=\"project-decision\"><span>02</span><div><h3>Fabricate around real constraints</h3><p>Brackets, mounts, and fixes must be strong enough, inspectable, and achievable with the available tools.</p></div></article><article class=\"project-decision\"><span>03</span><div><h3>Coordinate mixed experience</h3><p>Tasks were divided so new and experienced members could contribute safely.</p></div></article></div>"},{"id":"documentation","label":"Documentation","html":"<div class=\"project-section-heading compact\"><div><p class=\"project-eyebrow\">Documentation</p><h2>Community building and hands-on fabrication.</h2></div></div><div class=\"project-gallery documentation-carousel gallery-count-2\"><figure class=\"landscape\"><button type=\"button\" data-lightbox data-caption=\"Community event — Cars and Coffee events built visibility, recruited support, and helped fund the motorsports program.\"><img loading=\"lazy\" src=\"assets/images/motorsports-thebigpicture-1.jpg\" alt=\"Sierra College Cars and Coffee event\"></button><figcaption><strong>Community event</strong>Cars and Coffee events built visibility, recruited support, and helped fund the motorsports program.</figcaption></figure><figure class=\"portrait\"><button type=\"button\" data-lightbox data-caption=\"Track-driven fabrication — Repairs and brackets were developed around packaging, schedule, safety, and service constraints.\"><img loading=\"lazy\" src=\"assets/images/motorsports-img-5023-2.jpg\" alt=\"Fabricated motorsports component\"></button><figcaption><strong>Track-driven fabrication</strong>Repairs and brackets were developed around packaging, schedule, safety, and service constraints.</figcaption></figure></div>"},{"id":"results","label":"Results","html":"<div class=\"project-section-heading compact\"><div><p class=\"project-eyebrow\">Results</p><h2>The program connected leadership with physical engineering work.</h2></div></div><div class=\"project-outcome-grid compact-outcomes\"><article><span>01</span><h3>Sustained team activity</h3><p>Events and outreach created a practical funding and recruitment pipeline.</p></article><article><span>02</span><h3>Real repair experience</h3><p>Failures were diagnosed and corrected under race-preparation deadlines.</p></article><article><span>03</span><h3>Leadership progression</h3><p>Responsibility grew from treasury to vice president and president.</p></article></div>"},{"id":"references","label":"References","html":"<div class=\"project-section-heading compact\"><div><p class=\"project-eyebrow\">References</p><h2>Upstream projects and technical references</h2></div></div><div class=\"reference-callout\"><p>The race program participated in the broader amateur endurance-racing ecosystem.</p><p><strong>My work:</strong> Student-team planning, repairs, fabrication support, community events, sponsorship, recruitment, budgeting, and trackside execution.</p><div class=\"project-reference-list\"><a class=\"project-reference-chip\" href=\"https://24hoursoflemons.com/\" rel=\"noreferrer\" target=\"_blank\">24 Hours of Lemons <span>↗</span></a></div></div>"}],"next":"Add race-day photos and a concise vehicle-development timeline when those records are available.","fallbackPage":"projects/motorsports/"},"espresso-machine":{"id":"espresso-machine","tone":"orange","eyebrow":"ME190 senior design","title":"Hybrid hand-actuated espresso machine","lede":"A compact senior-design system combining a hand-actuated pressure mechanism with heating, pumping, sensing, controls, electronics packaging, and formal engineering documentation.","status":["Active senior project","Team project","SendCutSend sponsored"],"image":"assets/images/me190-full-assembly.png","imageAlt":"SolidWorks full assembly drawing for the ME190 espresso machine","imageCaption":"SolidWorks full assembly drawing, scale 1:3.","imageFit":"contain","gallery":[{"src":"assets/images/me190-full-assembly.png","alt":"SolidWorks full assembly drawing for the ME190 espresso machine","title":"Full assembly","copy":"The 1:3 SolidWorks drawing documents the hand-actuated mechanism, brew group, reservoir, controls, and electronics packaging.","orientation":"landscape"},{"src":"assets/images/espresso-image-113.jpg","alt":"ME190 espresso machine lever mechanism prototype","title":"Lever mechanism","copy":"The mechanism translates hand input into the pressure path used for extraction.","orientation":"portrait"},{"src":"assets/images/espresso-img-4665.jpg","alt":"ME190 team presenting the espresso machine project","title":"Design presentation","copy":"The team presented requirements, architecture, and validation plans for the complete system.","orientation":"landscape"},{"src":"assets/images/espresso-group1-standing.jpg","alt":"ME190 espresso machine project team","title":"Project team","copy":"Mechanical, electrical, controls, documentation, and sponsored fabrication work were coordinated across the team.","orientation":"landscape"}],"metrics":[{"value":"9 bar","label":"target extraction pressure"},{"value":"2 oz ±10%","label":"target shot volume"},{"value":"25–30 s","label":"target pull time"},{"value":"$750","label":"SendCutSend store credit"}],"tabs":[{"id":"overview","label":"Overview","html":"<div class=\"project-section-heading compact\"><div><p class=\"project-eyebrow\">Overview</p><h2>A complete appliance system rather than a lever alone.</h2></div></div><div class=\"project-overview-grid\"><article><p class=\"project-eyebrow\">Mechanism</p><h3>Human input with controlled extraction</h3><p>The lever and linkage are designed around espresso pressure and volume targets.</p></article><article><p class=\"project-eyebrow\">Integration</p><h3>Thermal, fluid, electrical, and control systems</h3><p>The project combines the brew mechanism with heating, pumping, sensors, controls, packaging, and validation.</p></article></div>"},{"id":"engineering","label":"Engineering","html":"<div class=\"project-section-heading compact\"><div><p class=\"project-eyebrow\">Engineering</p><h2>The mechanism and controls must be designed together.</h2></div></div><div class=\"project-decision-grid compact-decisions\"><article class=\"project-decision\"><span>01</span><div><h3>Start from measurable targets</h3><p>Pressure, volume, time, and envelope constraints define the system architecture.</p></div></article><article class=\"project-decision\"><span>02</span><div><h3>Package for service and safety</h3><p>Water, heat, electrical hardware, and moving mechanisms need clear separation and access.</p></div></article><article class=\"project-decision\"><span>03</span><div><h3>Document the full assembly</h3><p>Drawings, revisions, interfaces, and team handoffs are treated as engineering outputs.</p></div></article></div>"},{"id":"documentation","label":"Documentation","html":"<div class=\"project-section-heading compact\"><div><p class=\"project-eyebrow\">Documentation</p><h2>CAD, mechanism, presentation, and team documentation.</h2></div></div><div class=\"project-gallery documentation-carousel gallery-count-4\"><figure class=\"landscape\"><button type=\"button\" data-lightbox data-caption=\"Full assembly — The 1:3 SolidWorks drawing documents the hand-actuated mechanism, brew group, reservoir, controls, and electronics packaging.\"><img loading=\"lazy\" src=\"assets/images/me190-full-assembly.png\" alt=\"SolidWorks full assembly drawing for the ME190 espresso machine\"></button><figcaption><strong>Full assembly</strong>The 1:3 SolidWorks drawing documents the hand-actuated mechanism, brew group, reservoir, controls, and electronics packaging.</figcaption></figure><figure class=\"portrait\"><button type=\"button\" data-lightbox data-caption=\"Lever mechanism — The mechanism translates hand input into the pressure path used for extraction.\"><img loading=\"lazy\" src=\"assets/images/espresso-image-113.jpg\" alt=\"ME190 espresso machine lever mechanism prototype\"></button><figcaption><strong>Lever mechanism</strong>The mechanism translates hand input into the pressure path used for extraction.</figcaption></figure><figure class=\"landscape\"><button type=\"button\" data-lightbox data-caption=\"Design presentation — The team presented requirements, architecture, and validation plans for the complete system.\"><img loading=\"lazy\" src=\"assets/images/espresso-img-4665.jpg\" alt=\"ME190 team presenting the espresso machine project\"></button><figcaption><strong>Design presentation</strong>The team presented requirements, architecture, and validation plans for the complete system.</figcaption></figure><figure class=\"landscape\"><button type=\"button\" data-lightbox data-caption=\"Project team — Mechanical, electrical, controls, documentation, and sponsored fabrication work were coordinated across the team.\"><img loading=\"lazy\" src=\"assets/images/espresso-group1-standing.jpg\" alt=\"ME190 espresso machine project team\"></button><figcaption><strong>Project team</strong>Mechanical, electrical, controls, documentation, and sponsored fabrication work were coordinated across the team.</figcaption></figure></div>"},{"id":"sponsorship","label":"Sponsorship","html":"<div class=\"project-section-heading compact\"><div><p class=\"project-eyebrow\">Sponsorship</p><h2>SendCutSend is supporting the senior project</h2></div></div><div class=\"sponsor-panel\"><strong>$750</strong><div><h3>Store credit plus merchandise</h3><p>The sponsorship gives the team access to externally manufactured sheet and plate components while adding an industry-facing milestone to the project.</p></div></div>"},{"id":"results","label":"Current Status","html":"<div class=\"project-section-heading compact\"><div><p class=\"project-eyebrow\">Results</p><h2>The design has a defined architecture, documented assembly, and external manufacturing support.</h2></div></div><div class=\"project-outcome-grid compact-outcomes\"><article><span>01</span><h3>Integrated CAD</h3><p>The full assembly captures the mechanical and control-system package.</p></article><article><span>02</span><h3>Prototype mechanism</h3><p>The lever concept has moved into physical development.</p></article><article><span>03</span><h3>Industry support</h3><p>SendCutSend is supporting the team with manufacturing credit and merchandise.</p></article></div>"},{"id":"references","label":"References","html":"<div class=\"project-section-heading compact\"><div><p class=\"project-eyebrow\">References</p><h2>Upstream projects and technical references</h2></div></div><div class=\"reference-callout\"><p>This is a Sacramento State ME190 team project documented through SolidWorks and senior-design deliverables.</p><p><strong>My work:</strong> Electrical fundamentals, controls planning, efficiency constraints, wattage calculations, system integration, documentation, and team coordination.</p><div class=\"project-reference-list\"><a class=\"project-reference-chip\" href=\"https://sendcutsend.com/\" rel=\"noreferrer\" target=\"_blank\">SendCutSend <span>↗</span></a></div></div>"}],"next":"Complete fabrication, integrate the thermal and fluid systems, and validate pressure, volume, time, and repeatability.","fallbackPage":"projects/espresso-machine/"},"uei-lab":{"id":"uei-lab","tone":"orange","eyebrow":"Professional test engineering","title":"UEI energy-efficiency testing","lede":"Standards-driven appliance and ventilation testing through University Enterprises and Sacramento State, including controlled fixtures, instrumentation, data collection, repairs, and documentation.","status":["Professional work","CEC-related testing","HVI 916-style procedures"],"image":"assets/images/uei-img-8868.jpg","imageAlt":"Residential fan airflow test duct","imageCaption":"Residential fan airflow test duct.","imageFit":"cover","gallery":[{"src":"assets/images/uei-img-8868.jpg","alt":"Residential fan airflow test duct","title":"Airflow test duct","copy":"The controlled geometry supports repeatable residential-fan airflow and CFM measurements.","orientation":"landscape"},{"src":"assets/images/uei-img-8870.jpg","alt":"Wood test room and fan fixture","title":"Controlled test room","copy":"The eight-foot test environment was built, sealed, and maintained for standards-driven testing.","orientation":"landscape"},{"src":"assets/images/manufacturing-img-8774.jpg","alt":"Wooden test fixture under construction","title":"Fixture construction","copy":"Practical fixture work included construction, sealing, repair, and preparation before measurement.","orientation":"portrait"}],"metrics":[{"value":"8 ft","label":"controlled test-room scale"},{"value":"CFM","label":"fan airflow measurements"},{"value":"Thermal","label":"wet/dry bulb and appliance tests"},{"value":"Standards","label":"procedure-driven documentation"}],"tabs":[{"id":"overview","label":"Overview","html":"<div class=\"project-section-heading compact\"><div><p class=\"project-eyebrow\">Overview</p><h2>Lab work where setup quality directly affects the result.</h2></div></div><div class=\"project-overview-grid\"><article><p class=\"project-eyebrow\">Fixtures</p><h3>Controlled environments</h3><p>Test rooms and airflow fixtures were built, sealed, repaired, and prepared before measurement.</p></article><article><p class=\"project-eyebrow\">Instrumentation</p><h3>Pressure, flow, temperature, and power</h3><p>Tubing, sensors, thermocouples, loggers, and controlled conditions were coordinated for repeatable testing.</p></article></div>"},{"id":"engineering","label":"Engineering","html":"<div class=\"project-section-heading compact\"><div><p class=\"project-eyebrow\">Engineering</p><h2>Repeatability starts before data collection.</h2></div></div><div class=\"project-decision-grid compact-decisions\"><article class=\"project-decision\"><span>01</span><div><h3>Control leakage and geometry</h3><p>Fixture condition and sealing affect airflow results.</p></div></article><article class=\"project-decision\"><span>02</span><div><h3>Record setup changes</h3><p>Repairs and configuration changes remain part of the test record.</p></div></article><article class=\"project-decision\"><span>03</span><div><h3>Follow the procedure</h3><p>Standards and safety determine the sequence, not convenience.</p></div></article></div>"},{"id":"documentation","label":"Documentation","html":"<div class=\"project-section-heading compact\"><div><p class=\"project-eyebrow\">Documentation</p><h2>Airflow fixtures and controlled test environments.</h2></div></div><div class=\"project-gallery documentation-carousel gallery-count-3\"><figure class=\"landscape\"><button type=\"button\" data-lightbox data-caption=\"Airflow test duct — The controlled geometry supports repeatable residential-fan airflow and CFM measurements.\"><img loading=\"lazy\" src=\"assets/images/uei-img-8868.jpg\" alt=\"Residential fan airflow test duct\"></button><figcaption><strong>Airflow test duct</strong>The controlled geometry supports repeatable residential-fan airflow and CFM measurements.</figcaption></figure><figure class=\"landscape\"><button type=\"button\" data-lightbox data-caption=\"Controlled test room — The eight-foot test environment was built, sealed, and maintained for standards-driven testing.\"><img loading=\"lazy\" src=\"assets/images/uei-img-8870.jpg\" alt=\"Wood test room and fan fixture\"></button><figcaption><strong>Controlled test room</strong>The eight-foot test environment was built, sealed, and maintained for standards-driven testing.</figcaption></figure><figure class=\"portrait\"><button type=\"button\" data-lightbox data-caption=\"Fixture construction — Practical fixture work included construction, sealing, repair, and preparation before measurement.\"><img loading=\"lazy\" src=\"assets/images/manufacturing-img-8774.jpg\" alt=\"Wooden test fixture under construction\"></button><figcaption><strong>Fixture construction</strong>Practical fixture work included construction, sealing, repair, and preparation before measurement.</figcaption></figure></div>"},{"id":"results","label":"Experience","html":"<div class=\"project-section-heading compact\"><div><p class=\"project-eyebrow\">Results</p><h2>The role developed practical test-engineering discipline.</h2></div></div><div class=\"project-outcome-grid compact-outcomes\"><article><span>01</span><h3>Standards exposure</h3><p>Procedures and compliance goals shaped the work.</p></article><article><span>02</span><h3>Instrumentation practice</h3><p>Pressure, flow, temperature, and power measurements were handled together.</p></article><article><span>03</span><h3>Documentation habits</h3><p>Setup, repairs, and changes were treated as part of the result.</p></article></div>"}],"next":"Add anonymized diagrams or sample data only when they can be shared appropriately.","fallbackPage":"projects/uei-lab/"},"abb-rexroth":{"id":"abb-rexroth","tone":"orange","eyebrow":"Industrial robotics coursework","title":"ABB and Rexroth robotics lab","lede":"Supervised ME165 coursework using ABB robot hardware and Rexroth controls, with attention to controller state, I/O, emergency-stop behavior, motion, and safe lab execution.","status":["ME165 coursework","ABB hardware","Rexroth controls"],"image":"assets/images/me165-image-111.jpg","imageAlt":"ABB robot and Rexroth controls in the ME165 laboratory","imageCaption":"ABB robot and Rexroth controller hardware.","imageFit":"contain","gallery":[{"src":"assets/images/me165-image-111.jpg","alt":"ABB robot and Rexroth controls in the ME165 laboratory","title":"Industrial robotics lab","copy":"The supervised setup connected robot hardware, controller interfaces, cabling, I/O, and emergency-stop behavior.","orientation":"portrait"}],"metrics":[{"value":"ABB","label":"industrial robot exposure"},{"value":"Rexroth","label":"controller platform"},{"value":"E-stop","label":"safety-state awareness"},{"value":"ME165","label":"hands-on coursework"}],"tabs":[{"id":"overview","label":"Overview","html":"<div class=\"project-section-heading compact\"><div><p class=\"project-eyebrow\">Overview</p><h2>Controls concepts connected to real industrial hardware.</h2></div></div><div class=\"project-overview-grid\"><article><p class=\"project-eyebrow\">Hardware</p><h3>Robot and controller interfaces</h3><p>The lab connected motion, I/O, cabling, state, and safety behavior to controls theory.</p></article><article><p class=\"project-eyebrow\">Scope</p><h3>Academic hands-on exposure</h3><p>The work is presented accurately as supervised coursework rather than production ownership.</p></article></div>"},{"id":"engineering","label":"Engineering","html":"<div class=\"project-section-heading compact\"><div><p class=\"project-eyebrow\">Engineering</p><h2>Safe state awareness came first.</h2></div></div><div class=\"project-decision-grid compact-decisions\"><article class=\"project-decision\"><span>01</span><div><h3>Understand the stop path</h3><p>Emergency-stop and controller state were part of every motion task.</p></div></article><article class=\"project-decision\"><span>02</span><div><h3>Observe before changing</h3><p>Robot, controller, and I/O state were checked before commands were issued.</p></div></article><article class=\"project-decision\"><span>03</span><div><h3>Document the actual scope</h3><p>Coursework and production experience are kept distinct.</p></div></article></div>"},{"id":"documentation","label":"Documentation","html":"<div class=\"project-section-heading compact\"><div><p class=\"project-eyebrow\">Documentation</p><h2>The supervised ABB and Rexroth lab setup.</h2></div></div><div class=\"project-gallery documentation-carousel gallery-count-1\"><figure class=\"portrait\"><button type=\"button\" data-lightbox data-caption=\"Industrial robotics lab — The supervised setup connected robot hardware, controller interfaces, cabling, I/O, and emergency-stop behavior.\"><img loading=\"lazy\" src=\"assets/images/me165-image-111.jpg\" alt=\"ABB robot and Rexroth controls in the ME165 laboratory\"></button><figcaption><strong>Industrial robotics lab</strong>The supervised setup connected robot hardware, controller interfaces, cabling, I/O, and emergency-stop behavior.</figcaption></figure></div>"},{"id":"results","label":"Experience","html":"<div class=\"project-section-heading compact\"><div><p class=\"project-eyebrow\">Results</p><h2>The lab created a useful foundation for automation work.</h2></div></div><div class=\"project-outcome-grid compact-outcomes\"><article><span>01</span><h3>Industrial context</h3><p>Controls concepts became connected to real equipment.</p></article><article><span>02</span><h3>Safety habits</h3><p>Motion and controller tasks were framed around safe execution.</p></article><article><span>03</span><h3>Troubleshooting foundation</h3><p>State, faults, interfaces, and hardware were considered together.</p></article></div>"},{"id":"references","label":"References","html":"<div class=\"project-section-heading compact\"><div><p class=\"project-eyebrow\">References</p><h2>Upstream projects and technical references</h2></div></div><div class=\"reference-callout\"><p>ABB and Bosch Rexroth are the upstream industrial platforms used in the supervised lab.</p><p><strong>My work:</strong> Coursework execution, controller interaction, state awareness, I/O exposure, safe motion procedures, and documentation.</p><div class=\"project-reference-list\"><a class=\"project-reference-chip\" href=\"https://new.abb.com/products/robotics\" rel=\"noreferrer\" target=\"_blank\">ABB Robotics <span>↗</span></a><a class=\"project-reference-chip\" href=\"https://www.boschrexroth.com/\" rel=\"noreferrer\" target=\"_blank\">Bosch Rexroth <span>↗</span></a></div></div>"}],"next":"Build on the foundation with more direct robot programming, I/O integration, and documented fault recovery.","fallbackPage":"projects/abb-rexroth/"},"makerspace-manufacturing":{"id":"makerspace-manufacturing","tone":"orange","eyebrow":"Work experience","title":"Manufacturing and makerspace experience","lede":"A summary of practical equipment, training, production, finishing, inventory, and handoff skills developed at the Sierra College Makerspace and Vanquish Products / ASB Products.","status":["Work experience","Equipment support","Production workflow"],"image":"assets/images/makerspace-laser-training.jpg","imageAlt":"Joseph working with another user at a makerspace laser cutter","imageCaption":"Laser-system user support in the Sierra College Makerspace.","imageFit":"cover","gallery":[{"src":"assets/images/makerspace-laser-training.jpg","alt":"Joseph working with another user at a makerspace laser cutter","title":"Laser-system support","copy":"User training included safe setup, file preparation, process checks, and supervised operation.","orientation":"landscape"},{"src":"assets/images/makerspace-prusa-mk4.jpg","alt":"Prusa MK4 printer assembled in the makerspace","title":"Printer setup","copy":"Makerspace work included assembling, configuring, maintaining, and supporting additive-manufacturing equipment.","orientation":"portrait"},{"src":"assets/images/manufacturing-img-8774.jpg","alt":"Woodworking fixture in a shop environment","title":"Hands-on shop work","copy":"The role required practical setup, safe tool use, troubleshooting, and clear handoff to other users.","orientation":"portrait"}],"metrics":[{"value":"2 roles","label":"makerspace + production"},{"value":"CAD/CAM","label":"machine and file setup"},{"value":"Training","label":"safe user support"},{"value":"Finish","label":"deburr, inspect, pack, ship"}],"tabs":[{"id":"overview","label":"Roles","html":"<div class=\"project-section-heading compact\"><div><p class=\"project-eyebrow\">Experience summary</p><h2>Practical skills developed across the makerspace and production floor</h2></div></div><div class=\"project-role-grid\"><article><p class=\"project-eyebrow\">Sierra College Makerspace</p><h3>Makerspace Technical Assistant</h3><ul><li>3D printers, CNC routers, laser systems, woodworking, vinyl, and embroidery equipment.</li><li>CAD/CAM support, setup, troubleshooting, maintenance, user training, and shop safety.</li><li>Helped users move from an idea to a safe and workable process.</li></ul></article><article><p class=\"project-eyebrow\">Vanquish Products / ASB Products</p><h3>Inventory and Factory Support</h3><ul><li>Inventory management and production staging for machined RC components.</li><li>Deburring, polishing, cleaning, inspection, anodizing or laser-etch preparation, packaging, and shipping.</li><li>Production workflow discipline from receiving through final handoff.</li></ul></article></div>"},{"id":"documentation","label":"Documentation","html":"<div class=\"project-section-heading compact\"><div><p class=\"project-eyebrow\">Documentation</p><h2>Makerspace equipment, user support, and hands-on shop work.</h2></div></div><div class=\"project-gallery documentation-carousel gallery-count-3\"><figure class=\"landscape\"><button type=\"button\" data-lightbox data-caption=\"Laser-system support — User training included safe setup, file preparation, process checks, and supervised operation.\"><img loading=\"lazy\" src=\"assets/images/makerspace-laser-training.jpg\" alt=\"Joseph working with another user at a makerspace laser cutter\"></button><figcaption><strong>Laser-system support</strong>User training included safe setup, file preparation, process checks, and supervised operation.</figcaption></figure><figure class=\"portrait\"><button type=\"button\" data-lightbox data-caption=\"Printer setup — Makerspace work included assembling, configuring, maintaining, and supporting additive-manufacturing equipment.\"><img loading=\"lazy\" src=\"assets/images/makerspace-prusa-mk4.jpg\" alt=\"Prusa MK4 printer assembled in the makerspace\"></button><figcaption><strong>Printer setup</strong>Makerspace work included assembling, configuring, maintaining, and supporting additive-manufacturing equipment.</figcaption></figure><figure class=\"portrait\"><button type=\"button\" data-lightbox data-caption=\"Hands-on shop work — The role required practical setup, safe tool use, troubleshooting, and clear handoff to other users.\"><img loading=\"lazy\" src=\"assets/images/manufacturing-img-8774.jpg\" alt=\"Woodworking fixture in a shop environment\"></button><figcaption><strong>Hands-on shop work</strong>The role required practical setup, safe tool use, troubleshooting, and clear handoff to other users.</figcaption></figure></div>"},{"id":"engineering","label":"Skills","html":"<div class=\"project-section-heading compact\"><div><p class=\"project-eyebrow\">Engineering</p><h2>The work around the machine determines whether the process succeeds.</h2></div></div><div class=\"project-decision-grid compact-decisions\"><article class=\"project-decision\"><span>01</span><div><h3>Teach the process</h3><p>Good support helps the next job run safely without constant supervision.</p></div></article><article class=\"project-decision\"><span>02</span><div><h3>Treat finishing as production</h3><p>Deburring, cleaning, inspection, and packaging affect quality and customer experience.</p></div></article><article class=\"project-decision\"><span>03</span><div><h3>Protect equipment and people</h3><p>Setup, maintenance, training, and safety are part of uptime.</p></div></article></div>"},{"id":"results","label":"Experience","html":"<div class=\"project-section-heading compact\"><div><p class=\"project-eyebrow\">Results</p><h2>The roles connected design intent to real production work.</h2></div></div><div class=\"project-outcome-grid compact-outcomes\"><article><span>01</span><h3>Broader machine fluency</h3><p>I supported multiple tools and workflows instead of one narrow process.</p></article><article><span>02</span><h3>Operator-support habits</h3><p>Training, safety, and clear handoff became part of the technical solution.</p></article><article><span>03</span><h3>Production perspective</h3><p>Inventory, finishing, inspection, and shipping showed what happens after machining.</p></article></div>"}],"next":"Add future work samples only when they accurately represent the role and can be shared.","fallbackPage":"projects/makerspace-manufacturing/"}}};
